  return m;
}
function makeCone(tip, dir, mat) {
  const m = new THREE.Mesh(CONE, mat);
  const d = dir.clone().normalize();
  m.position.copy(tip).addScaledVector(d, -0.15);
  m.quaternion.setFromUnitVectors(UP, d);
  scene.add(m);
  return m;
}
function makeDot(r, mat, rim) {
  const g = new THREE.Group();
  const core = new THREE.Mesh(SPH, mat); core.scale.setScalar(r);
  const ring = new THREE.Mesh(SPH, rim); ring.scale.setScalar(r * 1.2);
  g.add(ring, core);
  scene.add(g);
  return g;
}

/* ── w = 0 plane (filled mint) ───────────────────────────────────────────── */
const PX0 = -2.2, PX1 = 1.6, PY0 = -2.2, PY1 = 2.2;
function quadCorners(w) {
  return [FIG(PX0, PY0, w), FIG(PX1, PY0, w), FIG(PX1, PY1, w), FIG(PX0, PY1, w)];
}
const c0 = quadCorners(0);
const quadGeo = new THREE.BufferGeometry();
quadGeo.setAttribute('position', new THREE.Float32BufferAttribute(
  [].concat(...c0.map(v => [v.x, v.y, v.z])), 3));
quadGeo.setIndex([0, 1, 2, 0, 2, 3]);
const mintPlane = new THREE.Mesh(quadGeo, new THREE.MeshBasicMaterial({
  color: 0xE3EDE9, transparent: true, opacity: 0.55,
  side: THREE.DoubleSide, depthWrite: false
}));
mintPlane.renderOrder = -1;
scene.add(mintPlane);
registerInteractive(mintPlane, {
  title: 'Heterogeneous plane (w = 0)',
  tooltip: 'w = 0 : the ordinary 2D plane',
  body: 'This is the ordinary Euclidean plane of heterogeneous coordinates (x, y). It has no w component at all.'
});

/* ── w = 1 plane (gray outline only) ─────────────────────────────────────── */
const c1 = quadCorners(1);
for (let i = 0; i < 4; i++) makeSeg(c1[i], c1[(i + 1) % 4], 0.022, matGrayPlane);

/* ── axes ────────────────────────────────────────────────────────────────── */
// w-axis (world +X)
makeSeg(FIG(0, 0, -0.4), FIG(0, 0, 3.6), 0.028, matBlack);
makeCone(FIG(0, 0, 3.6), new THREE.Vector3(1, 0, 0), matBlack);
// y-axis (world +Y)
makeSeg(FIG(0, -2.4, 0), FIG(0, 2.4, 0), 0.028, matBlack);
makeCone(FIG(0, 2.4, 0), new THREE.Vector3(0, 1, 0), matBlack);
// x-axis (world -Z), full line through the origin
makeSeg(FIG(-2.6, 0, 0), FIG(2.0, 0, 0), 0.028, matBlack);
makeCone(FIG(2.0, 0, 0), new THREE.Vector3(0, 0, -1), matBlack);
// tick at w = 1
makeSeg(FIG(0, -0.13, 1), FIG(0, 0.13, 1), 0.024, matBlack);

/* ── dynamic elements ────────────────────────────────────────────────────── */
let px = 0.55, py = 1.15, lambda = 1.0, classMode = false;

const leftDot = makeDot(0.10, matRed, matRim);
registerInteractive(leftDot, {
  title: 'The heterogeneous point (x, y)',
  tooltip: 'Drag me inside the w = 0 plane',
  body: 'Drag this dot: the whole homogeneous ray swings about the origin, but every point on that ray still names this one 2D point.'
});
const canonDot = makeDot(0.10, matRed, matRim);
registerInteractive(canonDot, {
  title: 'Canonical representative (x, y, 1)',
  tooltip: '(x, y, 1) on the w = 1 plane',
  body: 'Setting w = 1 selects one canonical member of the equivalence class. It is where the ray pierces the w = 1 plane.'
});
const farDot = makeDot(0.10, matRed, matRim);
registerInteractive(farDot, {
  title: 'Scaled representative (λx, λy, λ)',
  tooltip: '(λx, λy, λ)',
  body: 'Any nonzero multiple of (x, y, 1) is the same projective point: dividing through by w gives back (x/w, y/w).'
});
const connector = makeSeg(FIG(px, py, 0), FIG(px, py, 1), 0.012, matGrayThin);

const GHOST_L = [0.5, 1, 2];
const ghostDots = GHOST_L.map(() => {
  const g = makeDot(0.075, matGhost, matGhostRim);
  g.visible = false;
  return g;
});

// dashed ray pool
const dashPool = [];
for (let i = 0; i < 80; i++) {
  const m = new THREE.Mesh(CYL, matBlack);
  m.visible = false;
  scene.add(m);
  dashPool.push(m);
}
function updateDashRay(a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const L = dir.length();
  if (L < 1e-6) { dashPool.forEach(m => m.visible = false); return; }
  dir.divideScalar(L);
  const dash = 0.14, gap = 0.11;
  let s = 0, i = 0;
  while (s < L && i < dashPool.length) {
    const e = Math.min(s + dash, L);
    setSeg(dashPool[i],
      a.clone().addScaledVector(dir, s),
      a.clone().addScaledVector(dir, e), 0.018);
    dashPool[i].visible = true;
    i++;
    s = e + gap;
  }
  for (; i < dashPool.length; i++) dashPool[i].visible = false;
}

/* ── initial geometry state, then camera ─────────────────────────────────── */
function positionGeometry() {
  const lp = FIG(px, py, 0);
  const cp = FIG(px, py, 1);
  leftDot.position.copy(lp);
  canonDot.position.copy(cp);
  setSeg(connector, lp, cp, 0.012);
  const rayEnd = Math.max(2.9, lambda * 1.15);
  updateDashRay(new THREE.Vector3(0, 0, 0), FIG(px * rayEnd, py * rayEnd, rayEnd));
  farDot.position.copy(FIG(px * lambda, py * lambda, lambda));
  GHOST_L.forEach((L, i) => {
    ghostDots[i].position.copy(FIG(px * L, py * L, L));
    ghostDots[i].visible = classMode;
  });
}
positionGeometry();

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 15, z: 40 },
  heightFraction: 0.65
});

/* ── labels ──────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,"Times New Roman",serif;';
const IT = SER + 'font-style:italic;';

addLabel(`<span style="${IT}">y</span>`, FIG(0, 2.62, 0), { fontSize: '23px', offset: [-16, -4] });
addLabel(`<span style="${IT}">x</span>`, FIG(2.05, 0, 0), { fontSize: '23px', offset: [-22, -16] });
addLabel(`<span style="${IT}">w</span>`, FIG(0, 0, 3.7), { fontSize: '23px', offset: [10, 24] });
addLabel(`<span style="${SER}">1</span>`, FIG(0, -0.18, 1), { fontSize: '21px', offset: [-2, 16] });
addLabel(`<span style="${SER}">Heteregeneous</span>`, FIG(-3.0, 2.4, 0), { fontSize: '20px' });
addLabel(`<span style="${SER}">Homogeneous</span>`, FIG(-0.4, 2.1, 3.4), { fontSize: '20px' });

const lblXY = addLabel(`<span style="${IT}">(x,y)</span>`, FIG(px, py, 0),
  { fontSize: '20px', offset: [-32, -24] });
const lblXY1 = addLabel(`<span style="${IT}">(x,y,</span><span style="${SER}">1)</span>`,
  FIG(px, py, 1), { fontSize: '20px', offset: [36, 26] });
const lblFar = addLabel(`<span style="${IT}">(&lambda;x,&lambda;y,&lambda;)</span>`,
  FIG(px * lambda, py * lambda, lambda), { fontSize: '20px', offset: [4, -26] });

const ghostTxt = [
  '(0.5x,0.5y,0.5)',
  '(x,y,1)',
  '(2x,2y,2)'
];
const lblGhost = GHOST_L.map((L, i) => {
  const e = addLabel(`<span style="${IT}">${ghostTxt[i]}</span>`,
    FIG(px * L, py * L, L), { fontSize: '13px', color: '#b03030', offset: [-46, -12] });
  e.div.style.visibility = 'hidden';
  return e;
});

/* ── full update ─────────────────────────────────────────────────────────── */
const elLam = document.getElementById('lamVal');
const elRead = document.getElementById('readout');
const slider = document.getElementById('lambdaSlider');

function updateAll() {
  positionGeometry();
  lblXY.pos.copy(leftDot.position);
  lblXY1.pos.copy(canonDot.position);
  lblFar.pos.copy(farDot.position);
  GHOST_L.forEach((L, i) => {
    lblGhost[i].pos.copy(ghostDots[i].position);
    lblGhost[i].div.style.visibility = classMode ? 'visible' : 'hidden';
  });
  // hide the generic (λx,λy,λ) tag when the class labels take over
  lblFar.div.style.visibility = classMode ? 'hidden' : 'visible';
  lblXY1.div.style.visibility = classMode ? 'hidden' : 'visible';

  elLam.textContent = lambda.toFixed(2);
  elRead.innerHTML =
    `w = λ = ${lambda.toFixed(2)}<br>` +
    `(λx, λy, λ) = (${(px * lambda).toFixed(2)}, ${(py * lambda).toFixed(2)}, ${lambda.toFixed(2)})<br>` +
    `recover (x/w, y/w) = (${px.toFixed(2)}, ${py.toFixed(2)})`;
