updateAll();

/* ── slider ──────────────────────────────────────────────────────────────── */
slider.addEventListener('input', () => {
  tween = null;
  lambda = parseFloat(slider.value);
  updateAll();
});

/* ── class-view toggle ───────────────────────────────────────────────────── */
const btnCanon = document.getElementById('btnCanon');
const btnClass = document.getElementById('btnClass');
function setClassMode(on) {
  classMode = on;
  btnCanon.classList.toggle('active', !on);
  btnClass.classList.toggle('active', on);
  updateAll();
}
btnCanon.addEventListener('click', () => setClassMode(false));
btnClass.addEventListener('click', () => setClassMode(true));

/* ── dragging the (x,y) point inside the w = 0 plane ─────────────────────── */
const dragRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const wZeroPlane = new THREE.Plane(new THREE.Vector3(1, 0, 0), 0);
const hitPt = new THREE.Vector3();
let dragging = false;

function toNDC(ev) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (ev) => {
  toNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  if (dragRay.intersectObjects([leftDot], true).length) {
    dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture?.(ev.pointerId);
  }
});
canvas.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  toNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  if (dragRay.ray.intersectPlane(wZeroPlane, hitPt)) {
    px = THREE.MathUtils.clamp(-hitPt.z, PX0 + 0.1, PX1 - 0.1);
    py = THREE.MathUtils.clamp(hitPt.y, PY0 + 0.1, PY1 - 0.1);
    updateAll();
  }
});
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  controls.enabled = true;
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Canonical lift',
    text: 'The point (x, y) in the left heterogeneous plane is lifted straight out along w to the canonical homogeneous point (x, y, 1) on the w = 1 plane.',
    lambda: 1, cls: false
  },
  {
    title: 'Slide along the ray',
    text: 'Pushing the representative out to λ = 2.4 gives (λx, λy, λ). It is a different 3D point, yet dividing by w recovers exactly the same (x, y) on the left.',
    lambda: 2.4, cls: false
  },
  {
    title: 'One ray, one point',
    text: 'Highlighting several scaled copies at once shows the whole ray through the origin as a single equivalence class mapping to one heterogeneous point.',
    lambda: 2, cls: true
  },
  {
    title: 'Shrink toward the origin',
    text: 'As λ approaches 0 the representative collapses toward the origin; the direction survives but the heterogeneous coordinates blow up — this is how points at infinity appear.',
    lambda: 0.3, cls: true
  }
];
let step = 0;
let tween = null;
let playTimer = null;

function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  document.getElementById('stepTitle').textContent = `${step + 1}. ${s.title}`;
  document.getElementById('stepText').textContent = s.text;
  setClassMode(s.cls);
  tween = { from: lambda, to: s.lambda, t0: performance.now(), dur: 750 };
}
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(step + 1); });
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(step - 1); });

const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play demo'; }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '⏸ Pause';
  goToStep(step + 1);
  playTimer = setInterval(() => goToStep(step + 1), 3200);
});

/* ── tween loop ──────────────────────────────────────────────────────────── */
(function tweenLoop() {
  requestAnimationFrame(tweenLoop);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k * k * (3 - 2 * k);
  lambda = tween.from + (tween.to - tween.from) * e;
  slider.value = String(lambda);
  updateAll();
  if (k >= 1) tween = null;
})();

goToStep(0);
// @FIGURE_CODE_END

