──────────────────────────────────────────────────────────────────────────── */

const FIG = (x, y, w) => new THREE.Vector3(w, y, -x);

/* ── shared geometry / materials ─────────────────────────────────────────── */
const CYL = new THREE.CylinderGeometry(1, 1, 1, 14);
const SPH = new THREE.SphereGeometry(1, 22, 16);
const CONE = new THREE.ConeGeometry(0.105, 0.32, 18);

const matBlack = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matGrayPlane = new THREE.MeshBasicMaterial({ color: 0x66807C });
const matGrayThin = new THREE.MeshBasicMaterial({ color: 0x555555 });
const matRed = new THREE.MeshBasicMaterial({ color: 0xEE1B18 });
const matRim = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.BackSide });
const matGhost = new THREE.MeshBasicMaterial({ color: 0xF08080 });
const matGhostRim = new THREE.MeshBasicMaterial({ color: 0x8a3030, side: THREE.BackSide });
const matBlue = new THREE.MeshBasicMaterial({ color: 0x1B63C8 });
const matBlueRim = new THREE.MeshBasicMaterial({ color: 0x0b2f61, side: THREE.BackSide });

const UP = new THREE.Vector3(0, 1, 0);
function setSeg(mesh, a, b, r) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.scale.set(r, Math.max(len, 1e-5), r);
  if (len > 1e-6) mesh.quaternion.setFromUnitVectors(UP, dir.clone().divideScalar(len));
}
function makeSeg(a, b, r, mat) {
  const m = new THREE.Mesh(CYL, mat);
  setSeg(m, a, b, r);
  scene.add(m);
  return m;
}
function makeCone(tip, dir, mat) {
  const m = new THREE.Mesh(CONE, mat);
  const dd = dir.clone().normalize();
  m.position.copy(tip).addScaledVector(dd, -0.16);
  m.quaternion.setFromUnitVectors(UP, dd);
  scene.add(m);
  return m;
}
function makeDot(r, mat, rim) {
  const g = new THREE.Group();
  const core = new THREE.Mesh(SPH, mat); core.scale.setScalar(r);
  const ring = new THREE.Mesh(SPH, rim); ring.scale.setScalar(r * 1.22);
  g.add(ring, core);
  scene.add(g);
  return g;
}

/* ── w = 0 plane (filled mint) ───────────────────────────────────────────── */
const PX0 = -2.3, PX1 = 1.5, PY0 = -2.3, PY1 = 2.2;
function quadCorners(w) {
  return [FIG(PX0, PY0, w), FIG(PX1, PY0, w), FIG(PX1, PY1, w), FIG(PX0, PY1, w)];
}
const c0 = quadCorners(0);
const quadGeo = new THREE.BufferGeometry();
quadGeo.setAttribute('position', new THREE.Float32BufferAttribute(
  [].concat(...c0.map(v => [v.x, v.y, v.z])), 3));
quadGeo.setIndex([0, 1, 2, 0, 2, 3]);
const mintPlane = new THREE.Mesh(quadGeo, new THREE.MeshBasicMaterial({
  color: 0xE3EDE9, transparent: true, opacity: 0.55,
  side: THREE.DoubleSide, depthWrite: false
}));
mintPlane.renderOrder = -1;
scene.add(mintPlane);
registerInteractive(mintPlane, {
  title: 'The heterogeneous plane (w = 0)',
  tooltip: 'w = 0 : the ordinary 2D plane',
  body: 'The ordinary Euclidean plane of heterogeneous coordinates (x, y), drawn here at w = 0. A 2D point has no w component at all — w is added only when we lift it into homogeneous coordinates.'
});

/* ── w = 1 plane (gray outline only) ─────────────────────────────────────── */
const c1 = quadCorners(1);
for (let i = 0; i < 4; i++) makeSeg(c1[i], c1[(i + 1) % 4], 0.024, matGrayPlane);

/* ── axes ────────────────────────────────────────────────────────────────── */
makeSeg(FIG(0, 0, -0.5), FIG(0, 0, 3.2), 0.030, matBlack);             // w
makeCone(FIG(0, 0, 3.2), new THREE.Vector3(1, 0, 0), matBlack);
makeSeg(FIG(0, -2.4, 0), FIG(0, 2.4, 0), 0.030, matBlack);             // y
makeCone(FIG(0, 2.4, 0), new THREE.Vector3(0, 1, 0), matBlack);
makeSeg(FIG(-2.6, 0, 0), FIG(2.0, 0, 0), 0.030, matBlack);             // x
makeCone(FIG(2.0, 0, 0), new THREE.Vector3(0, 0, -1), matBlack);
makeSeg(FIG(0, -0.15, 1), FIG(0, 0.15, 1), 0.026, matBlack);           // tick at w = 1

/* ── dynamic elements ────────────────────────────────────────────────────── */
let px = 0.50, py = 0.80, lambda = 2.90, classMode = false, infMode = false;
let tween = null;

const leftDot = makeDot(0.11, matRed, matRim);
registerInteractive(leftDot, {
  title: 'The heterogeneous point (x, y)',
  tooltip: 'Drag me inside the mint w = 0 plane',
  body: 'Drag this dot: the whole homogeneous line swings about the 3D origin, but every point on that line still names this one 2D point.'
});
const canonDot = makeDot(0.11, matRed, matRim);
registerInteractive(canonDot, {
  title: 'Canonical representative (x, y, 1)',
  tooltip: '(x, y, 1) — where the line meets w = 1',
  body: 'Choosing λ = 1 picks one canonical member of the equivalence class: the single place where the line through the origin pierces the w = 1 plane.'
});
const farDot = makeDot(0.11, matRed, matRim);
registerInteractive(farDot, {
  title: 'Scaled representative (λx, λy, λ)',
  tooltip: '(λx, λy, λ), λ ≠ 0',
  body: 'Any nonzero multiple of (x, y, 1) is the SAME projective point: dividing through by w gives back (λx/λ, λy/λ) = (x, y), whatever λ is.'
});
const connector = makeSeg(FIG(px, py, 0), FIG(px, py, 1), 0.013, matGrayThin);

const GHOST_L = [0.45, 1, 1.8];
const ghostDots = GHOST_L.map(() => {
  const g = makeDot(0.08, matGhost, matGhostRim);
  g.visible = false;
  return g;
});

const infDot = makeDot(0.09, matBlue, matBlueRim);
infDot.visible = false;

/* ── dash pools ──────────────────────────────────────────────────────────── */
function makePool(n, mat) {
  const pool = [];
  for (let i = 0; i < n; i++) {
    const m = new THREE.Mesh(CYL, mat);
    m.visible = false;
    m.scale.set(0, 0, 0);
    scene.add(m);
    pool.push(m);
  }
  return pool;
}
const dashPool = makePool(70, matBlack);
const infPool = makePool(30, matBlue);

function updateDashes(pool, a, b, r, dash, gap) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const L = dir.length();
  if (L < 1e-6) { pool.forEach(m => { m.visible = false; }); return; }
  dir.divideScalar(L);
  let s = 0, i = 0;
  while (s < L && i < pool.length) {
    const e = Math.min(s + dash, L);
    setSeg(pool[i], a.clone().addScaledVector(dir, s), a.clone().addScaledVector(dir, e), r);
    pool[i].visible = true;
    i++;
    s = e + gap;
  }
  for (; i < pool.length; i++) { pool[i].visible = false; pool[i].scale.set(0, 0, 0); }
}

/* ── geometry placement ──────────────────────────────────────────────────── */
const ORIGIN = new THREE.Vector3(0, 0, 0);
function positionGeometry() {
  const lp = FIG(px, py, 0);
  const cp = FIG(px, py, 1);
  leftDot.position.copy(lp);
  canonDot.position.copy(cp);
  setSeg(connector, lp, cp, 0.013);

  const rayEnd = Math.max(lambda, classMode ? 2.6 : 1.25);
  updateDashes(dashPool, ORIGIN, FIG(px * rayEnd, py * rayEnd, rayEnd), 0.019, 0.15, 0.12);

  farDot.position.copy(FIG(px * lambda, py * lambda, lambda));
  GHOST_L.forEach((L, i) => {
    ghostDots[i].position.copy(FIG(px * L, py * L, L));
    ghostDots[i].visible = classMode;
  });

  const n = Math.hypot(px, py) || 1;
  const S = 2.1 / n;
  const ip = FIG(px * S, py * S, 0);
  infDot.position.copy(ip);
  infDot.visible = infMode;
  if (infMode) updateDashes(infPool, ORIGIN, ip, 0.017, 0.13, 0.11);
  else infPool.forEach(m => { m.visible = false; m.scale.set(0, 0, 0); });
}
positionGeometry();

/* ── camera (after all geometry) ─────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 8, z: 38 },
  heightFraction: 0.85
});

/* ── labels ──────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,"Times New Roman",serif;';
const IT = SER + 'font-style:italic;';

addLabel(`<span style="${IT}">y</span>`, FIG(0, 2.5, 0), { fontSize: '26px', offset: [20, -8] });
addLabel(`<span style="${IT}">x</span>`, FIG(2.0, 0, 0), { fontSize: '26px', offset: [-16, -22] });
addLabel(`<span style="${IT}">w</span>`, FIG(0, 0, 3.2), { fontSize: '26px', offset: [16, 26] });
addLabel(`<span style="${SER}">1</span>`, FIG(0, -0.18, 1), { fontSize: '22px', offset: [-2, 18] });
addLabel(`<span style="${SER}">Heteregeneous</span>`, FIG(-3.7, 1.92, 0), { fontSize: '21px' });
addLabel(`<span style="${SER}">Homogeneous</span>`, FIG(-1.0, 1.5, 3.3), { fontSize: '21px' });

const lblXY = addLabel(`<span style="${IT}">(x,y)</span>`, FIG(px, py, 0),
  { fontSize: '21px', offset: [-38, -24] });
const lblXY1 = addLabel(`<span style="${IT}">(x,y,</span><span style="${SER}">1)</span>`,
  FIG(px, py, 1), { fontSize: '21px', offset: [40, 28] });
const lblFar = addLabel(`<span style="${IT}">(&lambda;x,&lambda;y,&lambda;)</span>`,
  FIG(px * lambda, py * lambda, lambda), { fontSize: '21px', offset: [6, -28] });

const lblGhost = GHOST_L.map((L) => {
  const e = addLabel(`<span style="${IT}">&lambda; = ${L}</span>`, ORIGIN,
    { fontSize: '13px', color: '#a02828', offset: [-34, -14] });
  e.div.style.visibility = 'hidden';
  return e;
});

const lblInf = addLabel(
  `<span style="${IT}">(x,y,</span><span style="${SER}">0)</span>` +
  `<span style="${SER}font-size:12px;"> &mdash; point at infinity</span>`,
  ORIGIN, { fontSize: '17px', color: '#1B63C8', offset: [-8, -24] });
lblInf.div.style.visibility = 'hidden';

/* ── readouts / full update ──────────────────────────────────────────────── */
const elLam = document.getElementById('lamVal');
const elRead = document.getElementById('readout');
const slider = document.getElementById('lambdaSlider');

function updateAll() {
  positionGeometry();
  lblXY.pos.copy(leftDot.position);
  lblXY1.pos.copy(canonDot.position);
  lblFar.pos.copy(farDot.position);
  GHOST_L.forEach((L, i) => {
    lblGhost[i].pos.copy(ghostDots[i].position);
    lblGhost[i].div.style.visibility = classMode ? 'visible' : 'hidden';
  });
  lblInf.pos.copy(infDot.position);
  lblInf.div.style.visibility = infMode ? 'visible' : 'hidden';

  // when the class tags take over, drop the generic tags to avoid overlap
  lblFar.div.style.visibility = classMode ? 'hidden' : 'visible';
  lblXY1.div.style.visibility = classMode ? 'hidden' : 'visible';

  elLam.textContent = lambda.toFixed(2);
  elRead.innerHTML =
    `w = &lambda; = ${lambda.toFixed(2)}<br>` +
    `(&lambda;x, &lambda;y, &lambda;) = (${(px * lambda).toFixed(2)}, ${(py * lambda).toFixed(2)}, ${lambda.toFixed(2)})<br>` +
    `divide by w &rarr; (x, y) = (${px.toFixed(2)}, ${py.toFixed(2)}) <span style="color:#1a7f37">&#10003; unchanged</span>`;
}
updateAll();

/* ── slider ──────────────────────────────────────────────────────────────── */
slider.addEventListener('input', () => {
  tween = null;
  lambda = parseFloat(slider.value);
  updateAll();
});

/* ── view toggles ────────────────────────────────────────────────────────── */
const btnCanon = document.getElementById('btnCanon');
const btnClass = document.getElementById('btnClass');
function setClassMode(on) {
  classMode = on;
  btnCanon.classList.toggle('active', !on);
  btnClass.classList.toggle('active', on);
  updateAll();
}
btnCanon.addEventListener('click', () => setClassMode(false));
btnClass.addEventListener('click', () => setClassMode(true));

const btnInf = document.getElementById('btnInf');
function setInfMode(on) {
  infMode = on;
  btnInf.classList.toggle('active', on);
  btnInf.textContent = on ? 'Hide point at infinity (w = 0)' : 'Show point at infinity (w = 0)';
  updateAll();
}
btnInf.addEventListener('click', () => setInfMode(!infMode));

/* ── dragging the (x,y) point inside the w = 0 plane ─────────────────────── */
const dragRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const wZeroPlane = new THREE.Plane(new THREE.Vector3(1, 0, 0), 0);
const hitPt = new THREE.Vector3();
let dragging = false;

function toNDC(ev) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (ev) => {
  toNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  if (dragRay.intersectObjects([leftDot], true).length) {
    dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture?.(ev.pointerId);
  }
});
canvas.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  toNDC(ev);
  dragRay.setFromCamera(ndc, camera);
  if (dragRay.ray.intersectPlane(wZeroPlane, hitPt)) {
    px = THREE.MathUtils.clamp(-hitPt.z, PX0 + 0.15, PX1 - 0.15);
    py = THREE.MathUtils.clamp(hitPt.y, PY0 + 0.15, PY1 - 0.15);
    updateAll();
  }
});
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  controls.enabled = true;
});

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Reading the figure',
    text: '(x, y) is an ordinary 2D point in the mint plane. Its homogeneous representatives are all the multiples (λx, λy, λ) with λ ≠ 0 — one whole line through the 3D origin. The dashed line is that line, and the red dots are two of its representatives.',
    lambda: 2.9, cls: false, inf: false
  },
  {
    title: 'The canonical representative',
    text: 'Setting λ = 1 picks the single representative lying on the w = 1 plane: (x, y, 1). That is where the line pierces the plane, and it is what the thin grey connector points to.',
    lambda: 1, cls: false, inf: false
  },
  {
    title: 'Slide along the line',
    text: 'Move λ and the 3D point slides along the dashed line. The recovered 2D point (λx/λ, λy/λ) = (x, y) never changes — check the readout below.',
    lambda: 2.4, cls: false, inf: false
  },
  {
    title: 'One line, one point',
    text: 'Several scaled copies at once: they are all the same projective point. The homogeneous point IS the equivalence class {(λx, λy, λ) : λ ≠ 0} — the whole line, with the origin removed.',
    lambda: 1.8, cls: true, inf: false
  },
  {
    title: 'λ → 0, and points at infinity',
    text: 'As λ shrinks toward 0 the representative slides back toward the origin, yet dividing by w still returns exactly the same (x, y) — nothing blows up. Only λ = 0 is excluded: (0, 0, 0) names no point. A different triple with w = 0, namely (x, y, 0) shown in blue, lies inside the w = 0 plane and its line never meets w = 1 — that is a point at infinity, a pure direction.',
    lambda: 0.3, cls: true, inf: true
  }
];
let step = 0;
let playTimer = null;

function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  document.getElementById('stepTitle').textContent = `${step + 1}. ${s.title}`;
  document.getElementById('stepText').textContent = s.text;
  setClassMode(s.cls);
  setInfMode(s.inf);
  tween = { from: lambda, to: s.lambda, t0: performance.now(), dur: 800 };
}
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(step + 1); });
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(step - 1); });

const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '▶ Play demo'; }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '⏸ Pause';
  goToStep(step + 1);
  playTimer = setInterval(() => goToStep(step + 1), 4200);
});

/* ── tween loop ──────────────────────────────────────────────────────────── */
(function tweenLoop() {
  requestAnimationFrame(tweenLoop);
  if (!tween) return;
  const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
  const e = k * k * (3 - 2 * k);
  lambda = tween.from + (tween.to - tween.from) * e;
  slider.value = String(lambda);
  updateAll();
  if (k >= 1) tween = null;
})();

goToStep(0);
